Object.assign(HG.I18N.en, {"navRef": "Reference", "navDetect": "Smart Detect", "navDna": "DNA Engine", "navGen": "Generate", "navMidi": "MIDI Studio", "hdPreset": "Presets", "hdSave": "Save", "hdSettings": "Settings", "hdHelp": "Help", "hdNoPresets": "No saved presets yet", "hdBrowse": "Open preset browser…", "helpText": "Workspaces: Reference (load audio), Smart Detect (find regions), DNA Engine (similarity, variation, sampler, library), Generate (make a sound). MIDI Studio, Sound design and Presets hold the original generator.\n\nShortcuts: Ctrl/Cmd+1-7 switch pages, Space play, G generate, [ ] history, A swap A/B, Esc close settings.\n\nDetected regions are parts of the full mix, not separated stems.\n\nCtrl/Cmd+Z undo, Ctrl/Cmd+Shift+Z redo (Generate). Drag on the waveform snaps to bars; hold Alt for a free selection.", "saveAsk": "Save the whole setup as a preset.", "saveNeed": "Enter an artist and a name first.", "stReady": "READY", "stProc": "PROCESSING", "stDone": "COMPLETED", "stErr": "ERROR", "gnRegen": "Regenerate", "gnRegenHint": "Same seed as the last sound: restores the generated sound and resets the DNA sliders.", "gnRandom": "Randomize", "gnRandomHint": "New random seed and variation, then generates.", "gnPreview": "Preview", "gnSavePreset": "Save preset", "gnMain": "GENERATE VARIATION", "gnSummary": "{p}: similarity {sim}, variation {var}, seed {seed}", "dnaSim": "Similarity", "dnaVar": "Variation", "dnaTex": "Texture", "dnaTexHint": "Adds noise and drive to the generated sound.", "dnaMov": "Movement", "dnaMovHint": "Depth of LFO 1 (moves the filter if LFO 1 was unused).", "dnaBri": "Brightness", "dnaBriHint": "Filter cutoff of the generated sound.", "dnaHintOn": "Texture, Movement and Brightness edit the generated sound's real parameters (noise and drive, LFO 1 depth, filter cutoff). Centre = as generated.", "dnaHintOff": "Texture, Movement and Brightness are available after you generate a sound.", "dnaCoreGroup": "Character controls", "scSelected": "Selected", "scCands": "candidates", "scNoneHint": "No clear region of this type was found.", "rfRegion": "Selection {a} - {b} ({d})", "rfRegionNone": "Drag on the waveform to select a region."});
Object.assign(HG.I18N.tr, {"navRef": "Referans", "navDetect": "Smart Detect", "navDna": "DNA Motoru", "navGen": "Üret", "navMidi": "MIDI Stüdyo", "hdPreset": "Presetler", "hdSave": "Kaydet", "hdSettings": "Ayarlar", "hdHelp": "Yardım", "hdNoPresets": "Henüz kayıtlı preset yok", "hdBrowse": "Preset tarayıcısını aç…", "helpText": "Çalışma alanları: Referans (ses yükle), Smart Detect (bölge bul), DNA Motoru (benzerlik, varyasyon, örnekleyici, kütüphane), Üret (ses üret). MIDI Stüdyo, Ses tasarımı ve Presetler özgün üreticiyi içerir.\n\nKısayollar: Ctrl/Cmd+1-7 sayfalar, Boşluk çal, G üret, [ ] geçmiş, A A/B değiştir, Esc ayarları kapat.\n\nTespit edilen bölgeler tam miksin parçalarıdır, ayrıştırılmış stem değildir.\n\nCtrl/Cmd+Z geri al, Ctrl/Cmd+Shift+Z yinele (Üret). Dalga formunda sürükleme barlara hizalanır; serbest seçim için Alt.", "saveAsk": "Tüm kurulumu preset olarak kaydet.", "saveNeed": "Önce bir sanatçı ve ad gir.", "stReady": "HAZIR", "stProc": "İŞLENİYOR", "stDone": "TAMAMLANDI", "stErr": "HATA", "gnRegen": "Yeniden üret", "gnRegenHint": "Son sesle aynı tohum: üretilen sesi geri getirir ve DNA kaydırıcılarını sıfırlar.", "gnRandom": "Rastgele", "gnRandomHint": "Yeni rastgele tohum ve varyasyonla üretir.", "gnPreview": "Dinle", "gnSavePreset": "Preset kaydet", "gnMain": "VARYASYON ÜRET", "gnSummary": "{p}: benzerlik {sim}, varyasyon {var}, tohum {seed}", "dnaSim": "Benzerlik", "dnaVar": "Varyasyon", "dnaTex": "Doku", "dnaTexHint": "Üretilen sese gürültü ve sürücü ekler.", "dnaMov": "Hareket", "dnaMovHint": "LFO 1 derinliği (LFO 1 kullanılmıyorsa filtreyi hareket ettirir).", "dnaBri": "Parlaklık", "dnaBriHint": "Üretilen sesin filtre kesimi.", "dnaHintOn": "Doku, Hareket ve Parlaklık üretilen sesin gerçek parametrelerini düzenler (gürültü ve sürücü, LFO 1 derinliği, filtre kesimi). Orta = üretildiği gibi.", "dnaHintOff": "Doku, Hareket ve Parlaklık bir ses ürettikten sonra kullanılabilir.", "dnaCoreGroup": "Karakter kontrolleri", "scSelected": "Seçili", "scCands": "aday", "scNoneHint": "Bu türde net bir bölge bulunamadı.", "rfRegion": "Seçim {a} - {b} ({d})", "rfRegionNone": "Bölge seçmek için dalga formunda sürükle."});
Object.assign(HG.I18N.de, {"navRef": "Referenz", "navDetect": "Smart Detect", "navDna": "DNA-Engine", "navGen": "Erzeugen", "navMidi": "MIDI-Studio", "hdPreset": "Presets", "hdSave": "Speichern", "hdSettings": "Einstellungen", "hdHelp": "Hilfe", "hdNoPresets": "Noch keine Presets", "hdBrowse": "Preset-Browser öffnen…", "helpText": "Arbeitsbereiche: Referenz (Audio laden), Smart Detect (Bereiche finden), DNA-Engine (Ähnlichkeit, Variation, Sampler, Bibliothek), Erzeugen (Sound bauen). MIDI-Studio, Sounddesign und Presets enthalten den ursprünglichen Generator.\n\nTastenkürzel: Strg/Cmd+1-7 Seiten, Leertaste Play, G erzeugen, [ ] Verlauf, A A/B tauschen, Esc Einstellungen schließen.\n\nErkannte Bereiche sind Teile des Gesamtmixes, keine getrennten Stems.\n\nStrg/Cmd+Z rückgängig, Strg/Cmd+Umschalt+Z wiederholen (Generieren). Ziehen auf der Wellenform rastet auf Takte ein; Alt für freie Auswahl.", "saveAsk": "Das gesamte Setup als Preset speichern.", "saveNeed": "Gib zuerst Künstler und Namen ein.", "stReady": "BEREIT", "stProc": "LÄUFT", "stDone": "FERTIG", "stErr": "FEHLER", "gnRegen": "Neu erzeugen", "gnRegenHint": "Gleicher Seed wie der letzte Sound: stellt ihn wieder her und setzt die DNA-Regler zurück.", "gnRandom": "Zufall", "gnRandomHint": "Neuer Zufalls-Seed und Variation, dann erzeugen.", "gnPreview": "Vorhören", "gnSavePreset": "Preset speichern", "gnMain": "VARIATION ERZEUGEN", "gnSummary": "{p}: Ähnlichkeit {sim}, Variation {var}, Seed {seed}", "dnaSim": "Ähnlichkeit", "dnaVar": "Variation", "dnaTex": "Textur", "dnaTexHint": "Fügt dem Sound Rauschen und Drive hinzu.", "dnaMov": "Bewegung", "dnaMovHint": "Tiefe von LFO 1 (bewegt den Filter, wenn LFO 1 ungenutzt war).", "dnaBri": "Helligkeit", "dnaBriHint": "Filter-Cutoff des erzeugten Sounds.", "dnaHintOn": "Textur, Bewegung und Helligkeit ändern reale Parameter des Sounds (Rauschen und Drive, LFO-1-Tiefe, Filter-Cutoff). Mitte = wie erzeugt.", "dnaHintOff": "Textur, Bewegung und Helligkeit sind nach dem Erzeugen eines Sounds verfügbar.", "dnaCoreGroup": "Klangregler", "scSelected": "Gewählt", "scCands": "Kandidaten", "scNoneHint": "Kein klarer Bereich dieses Typs gefunden.", "rfRegion": "Auswahl {a} - {b} ({d})", "rfRegionNone": "Ziehe auf der Wellenform, um einen Bereich zu wählen."});
Object.assign(HG.I18N.es, {"navRef": "Referencia", "navDetect": "Smart Detect", "navDna": "Motor DNA", "navGen": "Generar", "navMidi": "Estudio MIDI", "hdPreset": "Presets", "hdSave": "Guardar", "hdSettings": "Ajustes", "hdHelp": "Ayuda", "hdNoPresets": "Aún no hay presets", "hdBrowse": "Abrir el explorador de presets…", "helpText": "Áreas: Referencia (cargar audio), Smart Detect (buscar regiones), Motor DNA (similitud, variación, sampler, biblioteca), Generar (crear un sonido). Estudio MIDI, Diseño de sonido y Presets contienen el generador original.\n\nAtajos: Ctrl/Cmd+1-7 páginas, Espacio reproducir, G generar, [ ] historial, A alternar A/B, Esc cerrar ajustes.\n\nLas regiones detectadas son partes de la mezcla completa, no stems separados.\n\nCtrl/Cmd+Z deshacer, Ctrl/Cmd+Mayús+Z rehacer (Generar). Arrastrar en la forma de onda se ajusta a compases; Alt para selección libre.", "saveAsk": "Guarda todo el ajuste como preset.", "saveNeed": "Escribe primero un artista y un nombre.", "stReady": "LISTO", "stProc": "PROCESANDO", "stDone": "COMPLETADO", "stErr": "ERROR", "gnRegen": "Regenerar", "gnRegenHint": "Misma semilla que el último sonido: lo restaura y reinicia los controles DNA.", "gnRandom": "Aleatorio", "gnRandomHint": "Nueva semilla y variación aleatorias, y genera.", "gnPreview": "Escuchar", "gnSavePreset": "Guardar preset", "gnMain": "GENERAR VARIACIÓN", "gnSummary": "{p}: similitud {sim}, variación {var}, semilla {seed}", "dnaSim": "Similitud", "dnaVar": "Variación", "dnaTex": "Textura", "dnaTexHint": "Añade ruido y saturación al sonido generado.", "dnaMov": "Movimiento", "dnaMovHint": "Profundidad del LFO 1 (mueve el filtro si el LFO 1 no se usaba).", "dnaBri": "Brillo", "dnaBriHint": "Corte del filtro del sonido generado.", "dnaHintOn": "Textura, Movimiento y Brillo editan parámetros reales del sonido (ruido y saturación, profundidad del LFO 1, corte del filtro). Centro = como se generó.", "dnaHintOff": "Textura, Movimiento y Brillo están disponibles tras generar un sonido.", "dnaCoreGroup": "Controles de carácter", "scSelected": "Seleccionado", "scCands": "candidatos", "scNoneHint": "No se halló una región clara de este tipo.", "rfRegion": "Selección {a} - {b} ({d})", "rfRegionNone": "Arrastra sobre la onda para elegir una región."});
Object.assign(HG.I18N.ar, {"navRef": "مرجع", "navDetect": "Smart Detect", "navDna": "محرك DNA", "navGen": "توليد", "navMidi": "استوديو MIDI", "hdPreset": "الإعدادات المسبقة", "hdSave": "حفظ", "hdSettings": "الإعدادات", "hdHelp": "مساعدة", "hdNoPresets": "لا توجد إعدادات محفوظة بعد", "hdBrowse": "فتح متصفح الإعدادات المسبقة…", "helpText": "مساحات العمل: مرجع (تحميل الصوت)، Smart Detect (إيجاد المناطق)، محرك DNA (التشابه، التنوع، السامبلر، المكتبة)، توليد (صنع صوت). استوديو MIDI وتصميم الصوت والإعدادات المسبقة تضم المولّد الأصلي.\n\nالاختصارات: Ctrl/Cmd+1-7 للصفحات، المسافة تشغيل، G توليد، [ ] السجل، A تبديل A/B، Esc إغلاق الإعدادات.\n\nالمناطق المكتشفة أجزاء من المزيج الكامل وليست مسارات معزولة.\n\nCtrl/Cmd+Z للتراجع، Ctrl/Cmd+Shift+Z للإعادة (التوليد). السحب على الموجة يحاذي الموازير؛ Alt لتحديد حر.", "saveAsk": "احفظ الإعداد كاملًا كإعداد مسبق.", "saveNeed": "أدخل اسم الفنان والاسم أولًا.", "stReady": "جاهز", "stProc": "قيد المعالجة", "stDone": "اكتمل", "stErr": "خطأ", "gnRegen": "إعادة التوليد", "gnRegenHint": "نفس بذرة آخر صوت: يستعيده ويعيد ضبط منزلقات DNA.", "gnRandom": "عشوائي", "gnRandomHint": "بذرة وتنوع عشوائيان جديدان ثم يولّد.", "gnPreview": "استماع", "gnSavePreset": "حفظ الإعداد", "gnMain": "ولّد تنوعًا", "gnSummary": "{p}: التشابه {sim}، التنوع {var}، البذرة {seed}", "dnaSim": "التشابه", "dnaVar": "التنوع", "dnaTex": "الملمس", "dnaTexHint": "يضيف ضجيجًا وتشويهًا للصوت المولَّد.", "dnaMov": "الحركة", "dnaMovHint": "عمق LFO 1 (يحرّك المرشح إن لم يكن مستخدمًا).", "dnaBri": "السطوع", "dnaBriHint": "قطع مرشح الصوت المولَّد.", "dnaHintOn": "الملمس والحركة والسطوع تعدّل معاملات الصوت الحقيقية (الضجيج والتشويه، عمق LFO 1، قطع المرشح). الوسط = كما وُلّد.", "dnaHintOff": "الملمس والحركة والسطوع متاحة بعد توليد صوت.", "dnaCoreGroup": "عناصر الطابع", "scSelected": "محدد", "scCands": "مرشحين", "scNoneHint": "لم تُعثر على منطقة واضحة من هذا النوع.", "rfRegion": "التحديد {a} - {b} ({d})", "rfRegionNone": "اسحب على الموجة لتحديد منطقة."});
Object.assign(HG.I18N.hi, {"navRef": "रेफ़रेंस", "navDetect": "Smart Detect", "navDna": "DNA इंजन", "navGen": "बनाएँ", "navMidi": "MIDI स्टूडियो", "hdPreset": "प्रीसेट", "hdSave": "सेव", "hdSettings": "सेटिंग", "hdHelp": "मदद", "hdNoPresets": "अभी कोई सेव प्रीसेट नहीं", "hdBrowse": "प्रीसेट ब्राउज़र खोलें…", "helpText": "वर्कस्पेस: रेफ़रेंस (ऑडियो लोड), Smart Detect (हिस्से खोजें), DNA इंजन (समानता, वैरिएशन, सैंपलर, लाइब्रेरी), बनाएँ (साउंड बनाएँ)। MIDI स्टूडियो, साउंड डिज़ाइन और प्रीसेट में मूल जनरेटर है।\n\nशॉर्टकट: Ctrl/Cmd+1-7 पेज, Space चलाएँ, G बनाएँ, [ ] इतिहास, A A/B बदलें, Esc सेटिंग बंद।\n\nपहचाने गए हिस्से पूरे मिक्स के भाग हैं, अलग किए स्टेम नहीं।\n\nCtrl/Cmd+Z पूर्ववत, Ctrl/Cmd+Shift+Z फिर करें (जनरेट)। वेवफ़ॉर्म पर खींचना बार पर स्नैप करता है; मुक्त चयन के लिए Alt।", "saveAsk": "पूरा सेटअप प्रीसेट के रूप में सेव करें।", "saveNeed": "पहले कलाकार और नाम लिखें।", "stReady": "तैयार", "stProc": "प्रोसेसिंग", "stDone": "पूरा हुआ", "stErr": "त्रुटि", "gnRegen": "फिर बनाएँ", "gnRegenHint": "पिछले साउंड का ही सीड: उसे वापस लाता है और DNA स्लाइडर रीसेट करता है।", "gnRandom": "रैंडम", "gnRandomHint": "नया रैंडम सीड और वैरिएशन, फिर बनाता है।", "gnPreview": "प्रीव्यू", "gnSavePreset": "प्रीसेट सेव करें", "gnMain": "वैरिएशन बनाएँ", "gnSummary": "{p}: समानता {sim}, वैरिएशन {var}, सीड {seed}", "dnaSim": "समानता", "dnaVar": "वैरिएशन", "dnaTex": "टेक्सचर", "dnaTexHint": "बने साउंड में नॉइज़ और ड्राइव जोड़ता है।", "dnaMov": "मूवमेंट", "dnaMovHint": "LFO 1 की गहराई (LFO 1 अनउपयोगी हो तो फ़िल्टर हिलाता है)।", "dnaBri": "ब्राइटनेस", "dnaBriHint": "बने साउंड का फ़िल्टर कटऑफ़।", "dnaHintOn": "टेक्सचर, मूवमेंट और ब्राइटनेस साउंड के असली पैरामीटर बदलते हैं (नॉइज़ और ड्राइव, LFO 1 गहराई, फ़िल्टर कटऑफ़)। बीच = जैसा बना।", "dnaHintOff": "साउंड बनाने के बाद टेक्सचर, मूवमेंट और ब्राइटनेस उपलब्ध होते हैं।", "dnaCoreGroup": "कैरेक्टर कंट्रोल", "scSelected": "चुना हुआ", "scCands": "उम्मीदवार", "scNoneHint": "इस प्रकार का स्पष्ट हिस्सा नहीं मिला।", "rfRegion": "चयन {a} - {b} ({d})", "rfRegionNone": "हिस्सा चुनने के लिए वेवफ़ॉर्म पर ड्रैग करें।"});
Object.assign(HG.I18N.en, {"snapBars": "Snap to bars", "snapHint": "Snaps a dragged selection to whole bars of the detected tempo. The grid starts at the first onset, so the downbeat is an estimate. Hold Alt for a free selection.", "rhythmTile": "Rhythm MIDI", "rhythmHint": "Drag into your DAW: a drum MIDI sketch of the selection (whole file if nothing is selected). Kick, snare and hat are guessed from a rough band and decay estimate of the full mix. Click to save.", "rhythmDone": "Rhythm sketch: {n} notes (kick {k}, snare {s}, hat {h}).", "rhythmNone": "No detected onsets here. Run Smart Detect first or widen the selection.", "libBatch": "Analyse folder…", "libBatchCancel": "Cancel folder analysis", "libBatchHint": "Analyses every audio file in a folder (up to 60) and saves the best bass, lead, pad and percussion region of each as a DNA profile. The folder name becomes the artist.", "batchProg": "Analysing {i}/{n}: {f}", "batchDone": "Folder done: {d} DNA profiles from {n} files.", "batchCancelled": "Folder analysis cancelled: {d} profiles from {n} files.", "batchNone": "No audio files in that folder.", "batchFail": "{f}: could not be analysed.", "gridBtn": "6 VARIATIONS", "gridTitle": "Six variations", "gridHint": "Same DNA, six seeds. Click to listen, Keep (or double-click) to use it. Arrows and 1-6 also work.", "gridKeep": "Keep", "gridClose": "Close", "undo": "Undo", "redo": "Redo", "undoNone": "Nothing to undo.", "redoNone": "Nothing to redo.", "tagDark": "Dark", "tagBright": "Bright", "tagWarm": "Warm", "tagPluck": "Pluck", "tagSoft": "Soft", "tagWide": "Wide", "tagNoisy": "Noisy", "tagMoving": "Moving", "tagSub": "Sub", "tagPitched": "Pitched", "tagUnpitched": "Unpitched"});
Object.assign(HG.I18N.tr, {"snapBars": "Bara hizala", "snapHint": "Sürüklenen seçimi algılanan tempoda tam barlara oturtur. Izgara ilk vuruşta başlar; ölçü başı bir tahmindir. Serbest seçim için Alt'a basılı tut.", "rhythmTile": "Ritim MIDI", "rhythmHint": "DAW'ına sürükle: seçimin (seçim yoksa tüm dosyanın) davul MIDI taslağı. Kick, snare ve hi-hat, tam miks üzerinde kaba bir bant ve sönüm tahminiyle seçilir. Kaydetmek için tıkla.", "rhythmDone": "Ritim taslağı: {n} nota (kick {k}, snare {s}, hi-hat {h}).", "rhythmNone": "Burada algılanmış vuruş yok. Önce Smart Detect çalıştır ya da seçimi genişlet.", "libBatch": "Klasörü analiz et…", "libBatchCancel": "Klasör analizini iptal et", "libBatchHint": "Bir klasördeki tüm ses dosyalarını (en çok 60) analiz eder; her birinin en iyi bas, lead, pad ve vurmalı bölgesini DNA profili olarak kaydeder. Klasör adı sanatçı olur.", "batchProg": "Analiz {i}/{n}: {f}", "batchDone": "Klasör bitti: {n} dosyadan {d} DNA profili.", "batchCancelled": "Klasör analizi iptal edildi: {n} dosyadan {d} profil.", "batchNone": "Bu klasörde ses dosyası yok.", "batchFail": "{f}: analiz edilemedi.", "gridBtn": "6 VARYASYON", "gridTitle": "Altı varyasyon", "gridHint": "Aynı DNA, altı tohum. Dinlemek için tıkla, kullanmak için Tut (ya da çift tıkla). Oklar ve 1-6 da çalışır.", "gridKeep": "Tut", "gridClose": "Kapat", "undo": "Geri al", "redo": "Yinele", "undoNone": "Geri alınacak bir şey yok.", "redoNone": "Yinelenecek bir şey yok.", "tagDark": "Karanlık", "tagBright": "Parlak", "tagWarm": "Sıcak", "tagPluck": "Pluck", "tagSoft": "Yumuşak", "tagWide": "Geniş", "tagNoisy": "Gürültülü", "tagMoving": "Hareketli", "tagSub": "Sub", "tagPitched": "Perdeli", "tagUnpitched": "Perdesiz"});
Object.assign(HG.I18N.de, {"snapBars": "Auf Takte rasten", "snapHint": "Rastet eine gezogene Auswahl auf ganze Takte des erkannten Tempos ein. Das Raster beginnt beim ersten Onset, die Eins ist also geschätzt. Alt halten für freie Auswahl.", "rhythmTile": "Rhythmus-MIDI", "rhythmHint": "In die DAW ziehen: ein Drum-MIDI-Entwurf der Auswahl (ohne Auswahl die ganze Datei). Kick, Snare und Hi-Hat werden grob über Band und Abklingen des Gesamtmixes geschätzt. Klicken zum Speichern.", "rhythmDone": "Rhythmus-Entwurf: {n} Noten (Kick {k}, Snare {s}, Hi-Hat {h}).", "rhythmNone": "Hier wurden keine Onsets erkannt. Erst Smart Detect ausführen oder die Auswahl vergrößern.", "libBatch": "Ordner analysieren…", "libBatchCancel": "Ordneranalyse abbrechen", "libBatchHint": "Analysiert alle Audiodateien eines Ordners (bis 60) und speichert die beste Bass-, Lead-, Pad- und Percussion-Region jeder Datei als DNA-Profil. Der Ordnername wird zum Künstler.", "batchProg": "Analyse {i}/{n}: {f}", "batchDone": "Ordner fertig: {d} DNA-Profile aus {n} Dateien.", "batchCancelled": "Ordneranalyse abgebrochen: {d} Profile aus {n} Dateien.", "batchNone": "Keine Audiodateien in diesem Ordner.", "batchFail": "{f}: konnte nicht analysiert werden.", "gridBtn": "6 VARIATIONEN", "gridTitle": "Sechs Variationen", "gridHint": "Gleiche DNA, sechs Seeds. Klicken zum Anhören, Behalten (oder Doppelklick) zum Übernehmen. Pfeile und 1-6 funktionieren auch.", "gridKeep": "Behalten", "gridClose": "Schließen", "undo": "Rückgängig", "redo": "Wiederholen", "undoNone": "Nichts rückgängig zu machen.", "redoNone": "Nichts zu wiederholen.", "tagDark": "Dunkel", "tagBright": "Hell", "tagWarm": "Warm", "tagPluck": "Pluck", "tagSoft": "Weich", "tagWide": "Breit", "tagNoisy": "Rauschig", "tagMoving": "Bewegt", "tagSub": "Sub", "tagPitched": "Tonal", "tagUnpitched": "Atonal"});
Object.assign(HG.I18N.es, {"snapBars": "Ajustar a compases", "snapHint": "Ajusta la selección arrastrada a compases completos del tempo detectado. La rejilla empieza en el primer ataque, así que el tiempo fuerte es una estimación. Mantén Alt para una selección libre.", "rhythmTile": "MIDI de ritmo", "rhythmHint": "Arrástralo a tu DAW: un boceto MIDI de batería de la selección (o de todo el archivo). Bombo, caja y charles se estiman de forma aproximada por banda y caída de la mezcla completa. Haz clic para guardar.", "rhythmDone": "Boceto de ritmo: {n} notas (bombo {k}, caja {s}, charles {h}).", "rhythmNone": "No hay ataques detectados aquí. Ejecuta Smart Detect o amplía la selección.", "libBatch": "Analizar carpeta…", "libBatchCancel": "Cancelar análisis de carpeta", "libBatchHint": "Analiza todos los archivos de audio de una carpeta (hasta 60) y guarda la mejor región de bajo, lead, pad y percusión de cada uno como perfil DNA. El nombre de la carpeta pasa a ser el artista.", "batchProg": "Analizando {i}/{n}: {f}", "batchDone": "Carpeta lista: {d} perfiles DNA de {n} archivos.", "batchCancelled": "Análisis cancelado: {d} perfiles de {n} archivos.", "batchNone": "No hay archivos de audio en esa carpeta.", "batchFail": "{f}: no se pudo analizar.", "gridBtn": "6 VARIACIONES", "gridTitle": "Seis variaciones", "gridHint": "Mismo DNA, seis semillas. Haz clic para escuchar y Conservar (o doble clic) para usarla. También funcionan las flechas y 1-6.", "gridKeep": "Conservar", "gridClose": "Cerrar", "undo": "Deshacer", "redo": "Rehacer", "undoNone": "Nada que deshacer.", "redoNone": "Nada que rehacer.", "tagDark": "Oscuro", "tagBright": "Brillante", "tagWarm": "Cálido", "tagPluck": "Pluck", "tagSoft": "Suave", "tagWide": "Amplio", "tagNoisy": "Ruidoso", "tagMoving": "Con movimiento", "tagSub": "Sub", "tagPitched": "Afinado", "tagUnpitched": "Sin altura"});
Object.assign(HG.I18N.ar, {"snapBars": "محاذاة إلى الموازير", "snapHint": "يحاذي التحديد المسحوب إلى موازير كاملة حسب الإيقاع المكتشف. تبدأ الشبكة عند أول ضربة، لذا بداية المازورة تقديرية. اضغط Alt لتحديد حر.", "rhythmTile": "إيقاع MIDI", "rhythmHint": "اسحبه إلى برنامج DAW: مسودة MIDI للطبول من التحديد (أو الملف كله). يُقدَّر الكيك والسنير والهاي هات تقديرًا تقريبيًا من النطاق والتلاشي في المزيج الكامل. انقر للحفظ.", "rhythmDone": "مسودة الإيقاع: {n} نوتة (كيك {k}، سنير {s}، هاي هات {h}).", "rhythmNone": "لا توجد ضربات مكتشفة هنا. شغّل Smart Detect أولًا أو وسّع التحديد.", "libBatch": "تحليل مجلد…", "libBatchCancel": "إلغاء تحليل المجلد", "libBatchHint": "يحلل كل الملفات الصوتية في مجلد (حتى 60) ويحفظ أفضل منطقة باس وليد وباد وإيقاع من كل ملف كملف DNA. يصبح اسم المجلد هو الفنان.", "batchProg": "تحليل {i}/{n}: {f}", "batchDone": "انتهى المجلد: {d} ملف DNA من {n} ملفات.", "batchCancelled": "أُلغي تحليل المجلد: {d} ملف من {n} ملفات.", "batchNone": "لا توجد ملفات صوتية في هذا المجلد.", "batchFail": "{f}: تعذّر التحليل.", "gridBtn": "6 تنويعات", "gridTitle": "ست تنويعات", "gridHint": "نفس DNA بست بذور. انقر للاستماع، و«احتفظ» (أو نقرة مزدوجة) للاستخدام. تعمل الأسهم و1-6 أيضًا.", "gridKeep": "احتفظ", "gridClose": "إغلاق", "undo": "تراجع", "redo": "إعادة", "undoNone": "لا شيء للتراجع عنه.", "redoNone": "لا شيء لإعادته.", "tagDark": "داكن", "tagBright": "ساطع", "tagWarm": "دافئ", "tagPluck": "نقري", "tagSoft": "ناعم", "tagWide": "واسع", "tagNoisy": "ضجيجي", "tagMoving": "متحرك", "tagSub": "عميق", "tagPitched": "نغمي", "tagUnpitched": "غير نغمي"});
Object.assign(HG.I18N.hi, {"snapBars": "बार पर स्नैप", "snapHint": "खींचे गए चयन को पहचाने गए टेम्पो के पूरे बार पर बैठाता है। ग्रिड पहले ऑनसेट से शुरू होता है, इसलिए डाउनबीट अनुमान है। मुक्त चयन के लिए Alt दबाए रखें।", "rhythmTile": "रिदम MIDI", "rhythmHint": "अपने DAW में खींचें: चयन (या पूरी फ़ाइल) का ड्रम MIDI ड्राफ़्ट। किक, स्नेयर और हाई-हैट पूरे मिक्स के बैंड और डिके से मोटे तौर पर अनुमानित हैं। सेव करने के लिए क्लिक करें।", "rhythmDone": "रिदम ड्राफ़्ट: {n} नोट्स (किक {k}, स्नेयर {s}, हाई-हैट {h})।", "rhythmNone": "यहाँ कोई ऑनसेट नहीं मिला। पहले Smart Detect चलाएँ या चयन बढ़ाएँ।", "libBatch": "फ़ोल्डर विश्लेषण…", "libBatchCancel": "फ़ोल्डर विश्लेषण रद्द करें", "libBatchHint": "फ़ोल्डर की हर ऑडियो फ़ाइल (60 तक) का विश्लेषण करता है और हर एक का सबसे अच्छा बास, लीड, पैड और परकशन हिस्सा DNA प्रोफ़ाइल के रूप में सेव करता है। फ़ोल्डर का नाम आर्टिस्ट बनता है।", "batchProg": "विश्लेषण {i}/{n}: {f}", "batchDone": "फ़ोल्डर पूरा: {n} फ़ाइलों से {d} DNA प्रोफ़ाइल।", "batchCancelled": "फ़ोल्डर विश्लेषण रद्द: {n} फ़ाइलों से {d} प्रोफ़ाइल।", "batchNone": "इस फ़ोल्डर में कोई ऑडियो फ़ाइल नहीं।", "batchFail": "{f}: विश्लेषण नहीं हो सका।", "gridBtn": "6 वेरिएशन", "gridTitle": "छह वेरिएशन", "gridHint": "एक ही DNA, छह सीड। सुनने के लिए क्लिक करें, इस्तेमाल के लिए रखें (या डबल-क्लिक)। तीर और 1-6 भी काम करते हैं।", "gridKeep": "रखें", "gridClose": "बंद करें", "undo": "पूर्ववत", "redo": "फिर करें", "undoNone": "पूर्ववत करने को कुछ नहीं।", "redoNone": "फिर करने को कुछ नहीं।", "tagDark": "डार्क", "tagBright": "ब्राइट", "tagWarm": "वार्म", "tagPluck": "प्लक", "tagSoft": "सॉफ़्ट", "tagWide": "वाइड", "tagNoisy": "नॉइज़ी", "tagMoving": "मूविंग", "tagSub": "सब", "tagPitched": "पिच्ड", "tagUnpitched": "अनपिच्ड"});
