Object.assign(HG.I18N.ar, {"skAuto": "المنتج التلقائي…", "skCo": "المنتج المساعد…", "apTitle": "المنتج التلقائي", "apHint": "اختر النوع والإيقاع والمقام والمدة والطاقة. يبني HitGen المقطوعة كاملة: الأقسام والإيقاع والباص والأكوردات واللحن والمؤثرات والأصوات.", "apGenre": "النوع", "apKey": "المقام", "apGo": "أنتج المقطوعة", "apDone": "{g}: {n} أقسام، {t}. أصبح MIDI المقطوعة والمسارات المنفصلة ومشروع FL Studio تتبع هذه المقطوعة.", "coTitle": "المنتج المساعد", "coHint": "حمّل ملف MIDI الخاص بك (لحن أو أكوردات أو باص). يكتشف HitGen مقامه ويختار الفكرة التي تتوافق أكوردها مع نغماتك أكثر ويكمل بقية الأجزاء. تبقى نغماتك مقفلة حتى لو غيّرت الأسلوب.", "coLoad": "حمّل ملف MIDI…", "coRole": "جزؤك", "coRoleMel": "لحن", "coRoleChords": "أكوردات", "coRoleBass": "باص", "coApply": "أكمل المقطوعة", "coNext": "توافق آخر", "coUnlock": "افتح قفل نغماتي", "coInfo": "{k} {s} (داخل السلم {c}%) · {r} · {b} مازورات · {n} نغمة", "coFit": "توافق {f}%: الأكوردات تتوافق مع نغماتك في {k} {s}. الخيار {i} من {m}. نغماتك مقفلة.", "coUnlocked": "فُتح قفل نغماتك؛ سيكتب HitGen هذا الجزء من جديد.", "coLocked": "مقفل: {n} ({r})", "coDrop": "أفلت ملف ‎.mid هنا أو اضغط تحميل.", "coReady": "جاهز. اضغط أكمل المقطوعة.", "coBadFile": "تعذّرت قراءة ملف MIDI هذا.", "coEmpty": "لا توجد نغمات في ملف MIDI خارج قناة الإيقاع.", "coSmpte": "ملفات MIDI بتوقيت SMPTE غير مدعومة؛ احفظه بالمازورات والنبضات."});
